{"items":[
  {
    "title": "Family and Social Networks in West Germany 1981",
    "url_or_doi": "https://doi.org/10.4232/1.12846",
    "justification": "Survey focuses on family life, partnership, marriage, kinship ties, and social networks in West Germany at the start of the 1980s."
  },
  {
    "title": "German General Social Survey – ALLBUS 1980",
    "url_or_doi": "https://doi.org/10.4232/1.13376",
    "justification": "Includes modules on family life, marital status, household composition, and attitudes toward family and gender roles in Germany in 1980."
  },
  {
    "title": "German General Social Survey – ALLBUS 1982",
    "url_or_doi": "https://doi.org/10.4232/1.13377",
    "justification": "Covers socio‑demographic variables including marriage, partnership, children, and family-related attitudes in early‑1980s West Germany."
  },
  {
    "title": "German General Social Survey – ALLBUS 1984",
    "url_or_doi": "https://doi.org/10.4232/1.13378",
    "justification": "ALLBUS 1984 contains questions on marital status, family composition, and value orientations concerning family and gender in West Germany."
  },
  {
    "title": "German General Social Survey – ALLBUS 1986",
    "url_or_doi": "https://doi.org/10.4232/1.13379",
    "justification": "Provides data on marriage, partnership, household, and attitudes toward family and gender roles in mid‑1980s West Germany."
  },
  {
    "title": "German General Social Survey – ALLBUS 1988",
    "url_or_doi": "https://doi.org/10.4232/1.13380",
    "justification": "Includes information on marital status, family structure, and family-related value orientations in West Germany at the end of the 1980s."
  },
  {
    "title": "German Family Panel (Pairfam) – Pilot Study 1988",
    "url_or_doi": "https://search.gesis.org/research_data/ZA3859",
    "justification": "Pilot panel concentrates on partnership, marriage intentions, fertility, and family relations in Germany, with data collection at the end of the 1980s."
  },
  {
    "title": "Family and Fertility Survey in the Federal Republic of Germany 1988 (FFS Germany)",
    "url_or_doi": "https://search.gesis.org/research_data/ZA2473",
    "justification": "Dedicated study of family life, marriage and partnership histories, and fertility behaviour in West Germany in the late 1980s."
  },
  {
    "title": "Youth and Family in the Federal Republic of Germany 1985",
    "url_or_doi": "https://search.gesis.org/research_data/ZA1443",
    "justification": "Focuses on young people’s relationships with parents, partnership, attitudes to marriage and family, and living arrangements in mid‑1980s West Germany."
  },
  {
    "title": "Marriage, Partnership and Living Arrangements in the Federal Republic of Germany 1986",
    "url_or_doi": "https://search.gesis.org/research_data/ZA1644",
    "justification": "Specialized survey on marital status, cohabitation, partnership histories, and family living arrangements in Germany in 1986."
  }
]}
